from collections import deque

def get_connected_components(grid, bg_color):
    """Find connected components of non-background cells"""
    h, w = len(grid), len(grid[0])
    visited = [[False] * w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if not visited[r][c] and grid[r][c] != bg_color:
                # BFS to collect all cells in this component
                comp_cells = []
                queue = deque([(r, c)])
                visited[r][c] = True

                while queue:
                    cr, cc = queue.popleft()
                    comp_cells.append((cr, cc))

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                            if grid[nr][nc] == grid[r][c] and grid[nr][nc] != bg_color:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                # Compute bounding box
                top_r = min(cell[0] for cell in comp_cells)
                bot_r = max(cell[0] for cell in comp_cells)
                left_c = min(cell[1] for cell in comp_cells)
                right_c = max(cell[1] for cell in comp_cells)
                color = grid[r][c]

                # Check if this forms a valid thick-bordered rectangle
                # All border cells should be same color
                # Interior should be background
                border_ok = True
                interior_clear = True

                for rr in range(top_r, bot_r + 1):
                    for cc in range(left_c, right_c + 1):
                        if rr == top_r or rr == bot_r or cc == left_c or cc == right_c:
                            if grid[rr][cc] != color:
                                border_ok = False
                        else:
                            if grid[rr][cc] != bg_color:
                                interior_clear = False

                if border_ok and interior_clear:
                    int_size = (bot_r - top_r - 1) * (right_c - left_c - 1)
                    components.append({
                        'top': top_r, 'bot': bot_r, 'left': left_c, 'right': right_c,
                        'color': color, 'int_size': int_size
                    })

    return components

